{"implementation":"def solve(case):
    nodes = case['nodes']
    required_symbols = set(case['required_symbols'])
    node_map = {n['id']: n for n in nodes}
    non_removable_ids = {n['id'] for n in nodes if not n['removable']}
    covered_by_nonremovable = set()
    for nid in non_removable_ids:
        sym = node_map[nid]['symbol']
        if sym in required_symbols:
            covered_by_nonremovable.add(sym)
    retain_removable = set()
    for sym in required_symbols:
        if sym not in covered_by_nonremovable:
            candidates = [n for n in nodes if n['removable'] and n['symbol'] == sym]
            if candidates:
                candidates.sort(key=lambda x: (-x['utility'], x['id']))
                best_id = candidates[0]['id']
                retain_removable.add(best_id)
                covered_by_nonremovable.add(sym)
    retained = non_removable_ids.union(retain_removable)
    all_ids = {n['id'] for n in nodes}
    removed = all_ids - retained
    return {"removed_node_ids": sorted(removed), "retained_node_ids": sorted(retained)}"}
